from datetime import datetime

def run(ctx):
    # Step 1: Create the new Size attribute option 'XXXL' on the existing 'size' attribute
    size_attr_state = ctx.reach("Locate and edit the size product attribute", success={"entity": "Product Attributes", "Attribute Code": "size"})
    size_attr_row = ctx.query(size_attr_state, entity="Product Attributes", fields=["Attribute Code"], filters={"Attribute Code": "size"})

    if not size_attr_row:
        raise ValueError("Size attribute not found")

    # Commit the new 'XXXL' option to the size attribute
    ctx.commit("Add XXXL option to size attribute", target=size_attr_row[0], values={
        "Admin Description": "XXXL",
        "Admin Swatch": "XXXL"
    })

    # Step 2: Locate the configurable parent product 'Minerva LumaTech V-Tee'
    # Branch: Query full mention first, then fallback to partial
    product_state = ctx.reach("Locate the Minerva LumaTech V-Tee product", success={"entity": "Products", "Name": "Minerva LumaTech V-Tee", "Type": "Configurable Product"})
    products = ctx.query(product_state, entity="Products", fields=["Name", "Type"], filters={"Name": "Minerva LumaTech V-Tee", "Type": "Configurable Product"})

    if not products:
        products = ctx.query(product_state, entity="Products", fields=["Name", "Type"], filters={"Name": "Minerva", "Type": "Configurable Product"})

    if not products:
        raise ValueError("Configurable product 'Minerva LumaTech V-Tee' not found")

    parent_product = products[0]

    # Step 3: Add the green/XXXL configuration to the parent
    ctx.commit("Add green XXXL configuration to Minerva LumaTech V-Tee", target=parent_product, values={
        "Configurations": [{"Color": "green", "Size": "XXXL"}]
    })

